import { afterAll, beforeAll, beforeEach, expect, test } from 'vitest'
import { chromium, type Browser, type Route } from 'playwright'
import { getPlatformProxy } from 'wrangler'
import server from '../../server'
import { applyMigrations } from '../db/test-migrations'
import {
  resetTables,
  seedPublic,
  signIn,
  TEST_ORIGIN,
  testEnv,
} from '../publication/test-support'
import { japaneseOutside } from './test-japanese'

// The pages are generated by `pnpm build`; CI builds before testing.
const platform = await getPlatformProxy<Env>({ persist: false })
const db = platform.env.DB
const env = testEnv(platform.env)

let browser: Browser
beforeAll(async () => {
  await applyMigrations(db)
  browser = await chromium.launch()
})
beforeEach(async () => {
  await resetTables(db)
  // Signing in records the handle "owner" from the stubbed GitHub login.
  await signIn(env)
})
afterAll(async () => {
  await browser?.close()
  await platform.dispose()
})

/** Opens the top page in English; `api` may replace the list answer. */
async function openEnglishTop(api?: (route: Route) => Promise<void>) {
  const page = await browser.newPage({ locale: 'en-US' })
  const errors: string[] = []
  page.on('console', (message) => {
    if (message.type() === 'error') errors.push(message.text())
  })
  await page.route('**/*', async (route) => {
    const url = new URL(route.request().url())
    if (url.origin !== TEST_ORIGIN) return route.abort()
    if (api && url.pathname === '/api/public/decks') return api(route)
    // Miniflare's local proxy refuses a foreign Origin; see home.browser.test.
    const { origin: _origin, ...headers } = await route.request().allHeaders()
    const response = await server.fetch(new Request(url, { headers }), env)
    await route.fulfill({
      status: response.status,
      headers: Object.fromEntries(response.headers),
      body: Buffer.from(await response.arrayBuffer()),
    })
  })
  await page.goto(`${TEST_ORIGIN}/`)
  return { page, errors }
}

test('Given a public deck and an English browser, When the top page lists it, Then the page and the date are English', async () => {
  await seedPublic(db, 'talk', 100, 'My talk')
  const { page, errors } = await openEnglishTop()
  await page.locator('.recent-list:not(.recent-loading)').waitFor()
  expect(await page.locator('html').getAttribute('lang')).toBe('en')
  expect(await page.locator('.recent-list time').textContent()).toBe(
    'Jan 1, 1970',
  )
  expect(japaneseOutside(await page.content())).toEqual([])
  expect(errors).toEqual([])
  await page.close()
})

test.each([
  [
    { status: 200, contentType: 'application/json', body: '[]' },
    'No slides have been published yet.',
  ],
  [{ status: 500, body: 'error' }, 'Could not load recent slides.'],
])(
  'Given the list answers %j, When the English top page settles, Then it says so in English',
  async (answer, message) => {
    const { page } = await openEnglishTop((route) => route.fulfill(answer))
    await page.getByText(message).waitFor()
    expect(japaneseOutside(await page.content())).toEqual([])
    await page.close()
  },
)

test('Given the English top page, When the reader picks Japanese, Then the Japanese page opens and stays chosen', async () => {
  const { page } = await openEnglishTop()
  await page.getByRole('link', { name: '日本語' }).click()
  await page.waitForURL(`${TEST_ORIGIN}/?lang=ja`)
  expect(await page.locator('html').getAttribute('lang')).toBe('ja')
  await page.goto(`${TEST_ORIGIN}/`)
  expect(await page.locator('html').getAttribute('lang')).toBe('ja')
  await page.close()
})
